create  proc [dbo].[ReportProductionDepartmentByDate] @From as datetime,@To as Datetime, @Login as nvarchar(max), @TypeBy as nvarchar(max), @String as nvarchar(max) as Declare @ReportName as nvarchar(max); if @TypeBy = 'ByDate' begin set @ReportName='Department Production Date Wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],d.department_name as LoginUser,pm.Date,pm.PRNo,@ReportName as ReportName,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType,iu.PkFactor as UnitQty, (Select Distinct(Unit) from unit  where UId=pd.UnitId) as UnitType, pd.Qty,pd.Rateperpcs,d.department_name from ProductionMasterDepartment pm inner join ProductionDetailDepartment pd on pm.PRId=pd.PRId inner join Store s on pm.SId=s.SId inner join Item i on pd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join DepartmentPOS d on pm.Did=d.Id where pm.Date between @From and @To order by pm.PRNo end else if @TypeBy = 'ByCategory' begin set @ReportName='Department Production Category Wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],d.department_name as LoginUser,pm.Date,pm.PRNo,@ReportName as ReportName,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType,iu.PkFactor as UnitQty, (Select Distinct(Unit) from unit  where UId=pd.UnitId) as UnitType, pd.Qty,pd.Rateperpcs,d.department_name from ProductionMasterDepartment pm inner join ProductionDetailDepartment pd on pm.PRId=pd.PRId inner join Store s on pm.SId=s.SId inner join Item i on pd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join DepartmentPOS d on pm.Did=d.Id inner join Split(@String,',') sp on sp.items = C.CId  where pm.Date between @From and @To order by pm.PRNo  end else if @TypeBy = 'BySubCategory' begin set @ReportName='Department Production Subcategory Wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],d.department_name as LoginUser,pm.Date,pm.PRNo,@ReportName as ReportName,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType,iu.PkFactor as UnitQty, (Select Distinct(Unit) from unit  where UId=pd.UnitId) as UnitType, pd.Qty,pd.Rateperpcs,d.department_name from ProductionMasterDepartment pm inner join ProductionDetailDepartment pd on pm.PRId=pd.PRId inner join Store s on pm.SId=s.SId inner join Item i on pd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join DepartmentPOS d on pm.Did=d.Id inner join Split(@String,',') sp on sp.items = sc.SBId where pm.Date between @From and @To order by pm.PRNo  end else if @TypeBy = 'ByItem' begin set @ReportName='Department Production Item Wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],d.department_name as LoginUser,pm.Date,pm.PRNo,@ReportName as ReportName,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType,iu.PkFactor as UnitQty, (Select Distinct(Unit) from unit  where UId=pd.UnitId) as UnitType, pd.Qty,pd.Rateperpcs,d.department_name from ProductionMasterDepartment pm inner join ProductionDetailDepartment pd on pm.PRId=pd.PRId inner join Store s on pm.SId=s.SId inner join Item i on pd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join DepartmentPOS d on pm.Did=d.Id inner join Split(@String,',') sp on sp.items = i.ItemId where pm.Date between @From and @To order by pm.PRNo  end else if @TypeBy = 'ByDepartment' begin set @ReportName='Department Production Report Department Wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],d.department_name as LoginUser,pm.Date,pm.PRNo,@ReportName as ReportName,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType,iu.PkFactor as UnitQty, (Select Distinct(Unit) from unit  where UId=pd.UnitId) as UnitType, pd.Qty,pd.Rateperpcs,d.department_name from ProductionMasterDepartment pm inner join ProductionDetailDepartment pd on pm.PRId=pd.PRId inner join Store s on pm.SId=s.SId inner join Item i on pd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join DepartmentPOS d on pm.Did=d.Id inner join Split(@String,',') sp on sp.items = d.id where pm.Date between @From and @To order by pm.PRNo  end